package com.notireader.app.data.mappers

import com.notireader.app.data.database.MessageEntity
import com.notireader.app.data.database.MessageMediaRelation
import com.notireader.app.domain.models.MessageModel
import com.notireader.app.domain.models.MessageWithMediaModel
import java.util.UUID

fun MessageModel.toMessageEntity(): MessageEntity {
    return MessageEntity(
        messageId = if (id == 0) UUID.randomUUID().toString() else id.toString(),
        sender = sender,
        message = message,
        timestamp = timestamp,
        isDeleted = isDeleted,
        sourcePackage = sourcePackage,
        isRead = isRead,
        iconRes = iconRes
    )
}

fun MessageEntity.toMessageModel(): MessageModel {
    return MessageModel(
        id = messageId.hashCode(),
        sender = sender,
        message = message,
        timestamp = timestamp,
        isDeleted = isDeleted,
        mediaPath = null, // Will be handled separately now
        sourcePackage = sourcePackage,
        isRead = isRead,
        iconRes = iconRes
    )
}

// New mappers for MessageWithMedia
fun MessageMediaRelation.toMessageWithMediaModel(): MessageWithMediaModel {
    return MessageWithMediaModel(
        id = message.messageId,
        sender = message.sender,
        message = message.message,
        timestamp = message.timestamp,
        isDeleted = message.isDeleted,
        sourcePackage = message.sourcePackage,
        isRead = message.isRead,
        iconRes = message.iconRes,
        mediaPaths = media.map { it.path }
    )
}

fun MessageMediaRelation.toMessageModel(): MessageModel {
    return MessageModel(
        id = message.messageId.hashCode(),
        sender = message.sender,
        message = message.message,
        timestamp = message.timestamp,
        isDeleted = message.isDeleted,
        mediaPath = media.firstOrNull()?.path, // Take first media for backward compatibility
        sourcePackage = message.sourcePackage,
        isRead = message.isRead,
        iconRes = message.iconRes
    )
}

fun MessageWithMediaModel.toMessageEntity(): MessageEntity {
    return MessageEntity(
        messageId = id,
        sender = sender,
        message = message,
        timestamp = timestamp,
        isDeleted = isDeleted,
        sourcePackage = sourcePackage,
        isRead = isRead,
        iconRes = iconRes
    )
}

package com.notireader.app.data.mappers
import com.notireader.app.data.database.MessageEntity import com.notireader.app.data.database.MessageWithMedia import com.notireader.app.domain.models.MessageModel import java.util.UUID
fun MessageModel.toMessageEntity(): MessageEntity { return MessageEntity( messageId = if (id.isBlank()) UUID.randomUUID().toString() else id, sender = sender, message = message, timestamp = timestamp, isDeleted = isDeleted, sourcePackage = sourcePackage, isRead = isRead, iconRes = iconRes ) }
fun MessageEntity.toMessageModel(): MessageModel { return MessageModel( id = messageId, sender = sender, message = message, timestamp = timestamp, isDeleted = isDeleted, mediaPaths = emptyList(), // Will be populated from MessageWithMedia sourcePackage = sourcePackage, isRead = isRead, iconRes = iconRes ) }
// New mappers for MessageWithMedia using your modified MessageModel fun MessageWithMedia.toMessageModel(): MessageModel { return MessageModel( id = message.messageId, sender = message.sender, message = message.message, timestamp = message.timestamp, isDeleted = message.isDeleted, mediaPaths = media.map { it.path }, sourcePackage = message.sourcePackage, isRead = message.isRead, iconRes = message.iconRes ) }

package com.notireader.app.data.repository

import android.util.Log
import androidx.lifecycle.LiveData
import androidx.lifecycle.map
import com.notireader.app.data.database.MessageDao
import com.notireader.app.data.mappers.toMessageEntity
import com.notireader.app.data.mappers.toMessageModel
import com.notireader.app.data.mappers.toMessageWithMediaModel
import com.notireader.app.domain.models.MessageModel
import com.notireader.app.domain.models.MessageWithMediaModel
import com.notireader.app.domain.repository.NotiRepository
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import java.util.UUID

class DefaultRepository(
    private val messageDao: MessageDao
) : NotiRepository {
    private val mutex = Mutex()

    // Existing methods (backward compatibility)
    override fun getAllMessages(): LiveData<List<MessageModel>> {
        return messageDao.getAllMessagesWithMedia().map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageModel() }
        }
    }

    override fun countUnreadMessagesForSender(sender: String): LiveData<Int> {
        return messageDao.countUnreadMessagesForSender(sender)
    }

    override suspend fun markMessageAsRead(sender: String) {
        messageDao.markMessagesAsRead(sender)
    }

    override suspend fun insertMessage(message: MessageModel) {
        withContext(Dispatchers.IO) {
            val messageEntity = message.toMessageEntity()
            val mediaPaths = if (message.mediaPath != null) listOf(message.mediaPath) else emptyList()
            messageDao.insertMessageWithMedia(messageEntity, mediaPaths)
        }
    }

    override suspend fun markMessageAsDeletedByDetails(sender: String, message: String, timestamp: Long) {
        withContext(Dispatchers.IO) {
            messageDao.markAsDeletedByDetails(sender, message, timestamp)
        }
    }

    override suspend fun onWhatsAppNotificationReceived(message: MessageModel) {
        Log.d("xyz", "onWhatsAppNotificationReceived: $message")
        val isDuplicate = mutex.withLock {
            messageDao.countSimilarMessages(message.sender, message.message, message.timestamp) > 0
        }
        if (!isDuplicate) {
            insertMessage(message)
        } else {
            Log.d("xyz", "Duplicate message detected, skipping insert: $message")
        }
    }

    override fun getMessagesForSender(sender: String): LiveData<List<MessageModel>> {
        return messageDao.getMessagesWithMediaForSender(sender).map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageModel() }
        }
    }

    override fun getMessagesForPackage(sourcePackage: String): LiveData<List<MessageModel>> {
        return messageDao.getMessagesWithMediaForPackage(sourcePackage).map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageModel() }
        }
    }

    override suspend fun isDuplicateMessage(sender: String, message: String, timestamp: Long): Boolean {
        return withContext(Dispatchers.IO) {
            messageDao.countSimilarMessages(sender, message, timestamp) > 0
        }
    }

    // New methods for multiple media support
    override fun getAllMessagesWithMedia(): LiveData<List<MessageWithMediaModel>> {
        return messageDao.getAllMessagesWithMedia().map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageWithMediaModel() }
        }
    }

    override fun getMessagesWithMediaForSender(sender: String): LiveData<List<MessageWithMediaModel>> {
        return messageDao.getMessagesWithMediaForSender(sender).map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageWithMediaModel() }
        }
    }

    override fun getMessagesWithMediaForPackage(sourcePackage: String): LiveData<List<MessageWithMediaModel>> {
        return messageDao.getMessagesWithMediaForPackage(sourcePackage).map { messageWithMediaList ->
            messageWithMediaList.map { it.toMessageWithMediaModel() }
        }
    }

    override suspend fun insertMessageWithMedia(message: MessageWithMediaModel) {
        withContext(Dispatchers.IO) {
            val messageEntity = message.toMessageEntity()
            messageDao.insertMessageWithMedia(messageEntity, message.mediaPaths)
        }
    }

    override suspend fun onWhatsAppNotificationReceivedWithMedia(message: MessageModel, mediaPaths: List<String>) {
        Log.d("xyz", "onWhatsAppNotificationReceivedWithMedia: $message, mediaPaths: $mediaPaths")
        val isDuplicate = mutex.withLock {
            messageDao.countSimilarMessages(message.sender, message.message, message.timestamp) > 0
        }
        if (!isDuplicate) {
            withContext(Dispatchers.IO) {
                val messageEntity = message.toMessageEntity()
                messageDao.insertMessageWithMedia(messageEntity, mediaPaths)
            }
            Log.d("xyz", "Message with media inserted: $message")
        } else {
            Log.d("xyz", "Duplicate message detected, skipping insert: $message")
        }
    }
}

