                    }

                    lower.endsWith(".mp3") || lower.endsWith(".opus") || lower.endsWith(".wav") || lower.endsWith(".m4a") -> {
                        binding.playButton.visibility = View.VISIBLE
                        binding.playButton.text = "Play Audio"
